def img(file,caption):return {'file':file,'caption':caption}
def ev(file,caption,**kw):return {'file':file,'caption':caption,**kw}
def section(title,paragraphs,**kw):return dict(title=title,paragraphs=paragraphs,**kw)
S['5']['sections'][3]['paragraphs'][1]='В Windows hosts имя devops.local сопоставлено адресу 192.168.56.101. AmneziaVPN перехватывал маршрут учебной подсети. Пользователь добавил адрес виртуальной машины в исключения VPN; после этого ping и SSH по имени прошли успешно, а HTTPS стал доступен напрямую через Host-only. Для SSH дополнительно сохранён проброс NAT 127.0.0.1:2222 → гостевой порт 2222. На сервере задано полное имя devops-vm.devops.local.'
S['5']['sections'][3]['paragraphs'].append('Для проверки блокировки выполнено обращение к порту 8080. В журнале UFW зафиксирован TCP SYN: IN=enp0s8 — входящий интерфейс Host-only; SRC=192.168.56.1 — Windows; DST=192.168.56.101 — сервер; DPT=8080 — запрещённый порт назначения. Метка UFW BLOCK подтверждает отбрасывание пакета; OUT пуст, поскольку пакет адресован самой виртуальной машине.')
S['5']['sections'][3]['evidence']=[ev('p5-hostname.txt','Разрешение имени и подключение после настройки исключения VPN')]
S['5']['sections'].append(section('6 Контрольные точки восстановления',['Созданы снимки 01-clean-install, 02-keys-configured и 03-ssh-hardened. Снимок 01 содержит обновлённую ОС до учебной настройки; 02 — учётную запись и ключевой вход; 03 — усиленную защиту SSH и UFW. Проверка восстановления от 01 выполнена в следующей работе и заняла 51,4 с после запуска измерения. Дополнительный исходный снимок сохранён.'],commands='01-clean-install\n02-keys-configured\n03-ssh-hardened'))
S['5']['appendices']=[{'title':'Приложение А. Сценарий проверки конфигурации','file':'scripts/audit.sh'}]
